const markOrderRefundFailed = `-- name: MarkOrderRefundFailed :exec
WITH failed_operation AS (
    UPDATE order_refund_operations
    SET status = CASE WHEN $1::BOOLEAN THEN 'needs_review' ELSE 'failed' END,
        error_message = $2,
        next_attempt_at = CURRENT_TIMESTAMP + make_interval(secs => $3::INT),
        updated_at = CURRENT_TIMESTAMP
    WHERE order_refund_operations.id = $4
    RETURNING cancellation_request_id
)
UPDATE event_cancellation_requests request
SET status = 'failed', updated_at = CURRENT_TIMESTAMP
FROM failed_operation
WHERE $1::BOOLEAN
  AND request.id = failed_operation.cancellation_request_id
`

