const rejectEventCancellation = `-- name: RejectEventCancellation :one
WITH reviewed AS (
    UPDATE event_cancellation_requests
    SET status = 'rejected', admin_note = $1, reviewed_by = $2,
        reviewed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
    WHERE event_cancellation_requests.id = $3 AND event_cancellation_requests.status = 'pending'
    RETURNING id, event_id, organizer_id, previous_event_status, previous_publish_at, previous_is_live, reason, evidence_url, status, fee_policy, admin_note, reviewed_by, reviewed_at, completed_at, created_at, updated_at
)
UPDATE events
SET status = (SELECT previous_event_status FROM reviewed),
    publish_at = (SELECT previous_publish_at FROM reviewed),
    is_live = (SELECT previous_is_live FROM reviewed)
WHERE id = (SELECT event_id FROM reviewed)
RETURNING (SELECT id FROM reviewed) AS request_id
`

type RejectEventCancellationParams struct {
	AdminNote  pgtype.Text `json:"admin_note"`
	ReviewedBy pgtype.UUID `json:"reviewed_by"`
	ID         pgtype.UUID `json:"id"`
}

func (q *Queries) RejectEventCancellation(ctx context.Context, arg RejectEventCancellationParams) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, rejectEventCancellation, arg.AdminNote, arg.ReviewedBy, arg.ID)
	var request_id pgtype.UUID
	err := row.Scan(&request_id)
	return request_id, err
}

const retryEventCancellationRefunds = `-- name: RetryEventCancellationRefunds :execrows
WITH retried AS (
    UPDATE order_refund_operations
    SET status = 'pending', attempt_count = 0, next_attempt_at = CURRENT_TIMESTAMP,
        error_message = NULL, updated_at = CURRENT_TIMESTAMP
    WHERE cancellation_request_id = $1
      AND status IN ('failed', 'needs_review')
    RETURNING cancellation_request_id
)
UPDATE event_cancellation_requests
SET status = 'refunding', updated_at = CURRENT_TIMESTAMP
WHERE id IN (SELECT cancellation_request_id FROM retried)
`

func (q *Queries) RetryEventCancellationRefunds(ctx context.Context, id pgtype.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, retryEventCancellationRefunds, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertManualRefundOperation = `-- name: UpsertManualRefundOperation :one
INSERT INTO order_refund_operations (
    order_id, source, fee_policy, status, stripe_refund_id, refund_amount_bani
)
VALUES ($1, 'stripe_dashboard', $2, $3, $4, $5)
ON CONFLICT (order_id) DO UPDATE SET
    source = CASE WHEN order_refund_operations.source = 'event_cancellation' THEN order_refund_operations.source ELSE 'stripe_dashboard' END,
    fee_policy = CASE WHEN order_refund_operations.source = 'event_cancellation' THEN order_refund_operations.fee_policy ELSE EXCLUDED.fee_policy END,
    status = CASE WHEN order_refund_operations.source = 'event_cancellation' THEN order_refund_operations.status ELSE EXCLUDED.status END,
    stripe_refund_id = COALESCE(order_refund_operations.stripe_refund_id, EXCLUDED.stripe_refund_id),
    refund_amount_bani = GREATEST(order_refund_operations.refund_amount_bani, EXCLUDED.refund_amount_bani),
    updated_at = CURRENT_TIMESTAMP
RETURNING id, order_id, cancellation_request_id, source, fee_policy, status, stripe_refund_id, stripe_application_fee_id, stripe_fee_refund_id, refund_amount_bani, application_fee_refunded_bani, attempt_count, next_attempt_at, error_message, created_at, updated_at
`

type UpsertManualRefundOperationParams struct {
	OrderID          pgtype.UUID `json:"order_id"`
	FeePolicy        string      `json:"fee_policy"`
	Status           string      `json:"status"`
	StripeRefundID   pgtype.Text `json:"stripe_refund_id"`
	RefundAmountBani int64       `json:"refund_amount_bani"`
}

func (q *Queries) UpsertManualRefundOperation(ctx context.Context, arg UpsertManualRefundOperationParams) (OrderRefundOperations, error) {
	row := q.db.QueryRow(ctx, upsertManualRefundOperation,
		arg.OrderID,
		arg.FeePolicy,
		arg.Status,
		arg.StripeRefundID,
		arg.RefundAmountBani,
	)
	var i OrderRefundOperations
	err := row.Scan(
		&i.ID,
		&i.OrderID,
		&i.CancellationRequestID,
		&i.Source,
		&i.FeePolicy,
		&i.Status,
		&i.StripeRefundID,
		&i.StripeApplicationFeeID,
		&i.StripeFeeRefundID,
		&i.RefundAmountBani,
		&i.ApplicationFeeRefundedBani,
		&i.AttemptCount,
		&i.NextAttemptAt,
		&i.ErrorMessage,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
